import java.io.Serializable;

public class JobEvent implements Serializable {

    public long timestampMicros;
    public long jobId;
    public int eventType;

    public JobEvent() {}

    public JobEvent(long timestampMicros, long jobId, int eventType) {
        this.timestampMicros = timestampMicros;
        this.jobId = jobId;
        this.eventType = eventType;
    }

    public long timestampMillis() {
        return timestampMicros / 1000L;
    }

    public static JobEvent fromCsvLine(String line) {
        String[] f = line.split(",", -1);
        if (f.length < 4) {
            throw new IllegalArgumentException("Invalid job event line, expected >=4 fields: " + line);
        }
        long ts = parseLongOrDefault(f[0], 0L);
        long jobId = parseLongOrDefault(f[2], 0L);
        int type = (int) parseLongOrDefault(f[3], -1L);
        return new JobEvent(ts, jobId, type);
    }

    private static long parseLongOrDefault(String s, long def) {
        if (s == null || s.isEmpty()) {
            return def;
        }
        return Long.parseLong(s);
    }
}
