", "new_str": "    private interface LineParser<T> {
        T parse(String line);
    }

    private interface TimestampExtractor<T> {
        long extractTimestampMillis(T event);
    }

    private static class TimestampedGzipCsvSource<T> implements SourceFunction<T> {

        private final String path;
        private final LineParser<T> parser;
        private final TimestampExtractor<T> timestampExtractor;
        private volatile boolean running = true;

        private TimestampedGzipCsvSource(String path, LineParser<T> parser, TimestampExtractor<T> timestampExtractor) {
            this.path = path;
            this.parser = parser;
            this.timestampExtractor = timestampExtractor;
        }

        @Override
        public void run(SourceContext<T> ctx) throws Exception {
            if (path == null) {
                throw new IllegalArgumentException("Input path is null");
            }

            long lastWatermark = Long.MIN_VALUE;
            final Object lock = ctx.getCheckpointLock();

            try (BufferedReader br = new BufferedReader(
                    new InputStreamReader(new GZIPInputStream(new java.io.FileInputStream(path)), StandardCharsets.UTF_8))) {

                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }

                    T parsed = parser.parse(line);
                    long ts = timestampExtractor.extractTimestampMillis(parsed);

                    synchronized (lock) {
                        ctx.collectWithTimestamp(parsed, ts);
                        if (ts > lastWatermark) {
                            lastWatermark = ts;
                            ctx.emitWatermark(new Watermark(ts));
                        }
                    }
                }

                synchronized (lock) {
                    ctx.emitWatermark(Watermark.MAX_WATERMARK);
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }
}
"}

