import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.functions.AggregateFunction;
import org.apache.flink.api.common.functions.FilterFunction;
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.datastream.KeyedStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.source.SourceFunction;
import org.apache.flink.streaming.api.windowing.assigners.EventTimeSessionWindows;
import org.apache.flink.streaming.api.windowing.time.Time;
import org.apache.flink.streaming.api.windowing.windows.TimeWindow;
import org.apache.flink.streaming.api.functions.windowing.ProcessWindowFunction;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    private static final int TASK_EVENT_SUBMIT = 0;
    private static final int JOB_EVENT_FAIL = 3;
    private static final int JOB_EVENT_FINISH = 4;
    private static final int JOB_EVENT_KILL = 5;

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);

        final int sesssizeSeconds = params.getInt("sesssize", 600);
        final long sessGapMs = sesssizeSeconds * 1000L;

        if (taskEvents == null && (taskInput == null || taskInput.isEmpty())) {
            throw new IllegalArgumentException("Missing required parameter task_input");
        }
        if (jobEvents == null && (jobInput == null || jobInput.isEmpty())) {
            throw new IllegalArgumentException("Missing required parameter job_input");
        }
        if (out == null && (outputPath == null || outputPath.isEmpty())) {
            throw new IllegalArgumentException("Missing required parameter output");
        }

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        SourceFunction<TaskEvent> taskSource = taskSourceOrTest(new GzipCsvSource<>(taskInput, TaskEvent::fromCsvLine));
        SourceFunction<JobEvent> jobSource = jobSourceOrTest(new GzipCsvSource<>(jobInput, JobEvent::fromCsvLine));

        WatermarkStrategy<TaskEvent> taskWm = WatermarkStrategy
                .<TaskEvent>forMonotonousTimestamps()
                .withTimestampAssigner((e, ts) -> e.timestampMillis());

        WatermarkStrategy<JobEvent> jobWm = WatermarkStrategy
                .<JobEvent>forMonotonousTimestamps()
                .withTimestampAssigner((e, ts) -> e.timestampMillis());

        DataStream<TaskEvent> submitTasks = env
                .addSource(taskSource)
                .assignTimestampsAndWatermarks(taskWm)
                .filter((FilterFunction<TaskEvent>) e -> e.eventType == TASK_EVENT_SUBMIT);

        KeyedStream<TaskEvent, Long> tasksByJob = submitTasks.keyBy(e -> e.jobId);

        DataStream<Tuple2<Long, Integer>> stageCounts = tasksByJob
                .window(EventTimeSessionWindows.withGap(Time.seconds(sesssizeSeconds)))
                .aggregate(new CountAgg(), new SessionCountToTuple());

        DataStream<Tuple2<Long, Long>> finishedJobs = env
                .addSource(jobSource)
                .assignTimestampsAndWatermarks(jobWm)
                .filter((FilterFunction<JobEvent>) e -> e.eventType == JOB_EVENT_FAIL || e.eventType == JOB_EVENT_FINISH || e.eventType == JOB_EVENT_KILL)
                .map((MapFunction<JobEvent, Tuple2<Long, Long>>) e -> Tuple2.of(e.jobId, e.timestampMillis()));

        DataStream<String> output = finishedJobs
                .keyBy(t -> t.f0)
                .connect(stageCounts.keyBy(t -> t.f0))
                .process(new EmitOnFinish(sessGapMs));

        output
                .addSink(sinkOrTest(new LocalFileSink(outputPath)))
                .setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    private static class CountAgg implements AggregateFunction<TaskEvent, Integer, Integer> {
        @Override
        public Integer createAccumulator() {
            return 0;
        }

        @Override
        public Integer add(TaskEvent value, Integer accumulator) {
            return accumulator + 1;
        }

        @Override
        public Integer getResult(Integer accumulator) {
            return accumulator;
        }

        @Override
        public Integer merge(Integer a, Integer b) {
            return a + b;
        }
    }

    private static class SessionCountToTuple extends ProcessWindowFunction<Integer, Tuple2<Long, Integer>, Long, TimeWindow> {
        @Override
        public void process(Long key, Context context, Iterable<Integer> elements, Collector<Tuple2<Long, Integer>> out) {
            Integer count = elements.iterator().next();
            out.collect(Tuple2.of(key, count));
        }
    }

    private static class EmitOnFinish extends KeyedCoProcessFunction<Long, Tuple2<Long, Long>, Tuple2<Long, Integer>, String> {

        private final long sessionGapMs;

        private transient ValueState<Integer> maxStageCount;
        private transient ValueState<Boolean> finished;
        private transient ValueState<Long> emitTimer;

        private EmitOnFinish(long sessionGapMs) {
            this.sessionGapMs = sessionGapMs;
        }

        @Override
        public void open(Configuration parameters) {
            maxStageCount = getRuntimeContext().getState(new ValueStateDescriptor<>("maxStageCount", Integer.class));
            finished = getRuntimeContext().getState(new ValueStateDescriptor<>("finished", Boolean.class));
            emitTimer = getRuntimeContext().getState(new ValueStateDescriptor<>("emitTimer", Long.class));
        }

        @Override
        public void processElement1(Tuple2<Long, Long> finishEvent, Context ctx, Collector<String> out) throws Exception {
            finished.update(true);

            long desiredTimer = finishEvent.f1 + sessionGapMs;
            Long currentTimer = emitTimer.value();

            if (currentTimer == null || desiredTimer > currentTimer) {
                if (currentTimer != null) {
                    ctx.timerService().deleteEventTimeTimer(currentTimer);
                }
                emitTimer.update(desiredTimer);
                ctx.timerService().registerEventTimeTimer(desiredTimer);
            }
        }

        @Override
        public void processElement2(Tuple2<Long, Integer> stageCount, Context ctx, Collector<String> out) throws Exception {
            Integer cur = maxStageCount.value();
            if (cur == null || stageCount.f1 > cur) {
                maxStageCount.update(stageCount.f1);
            }
        }

        @Override
        public void onTimer(long timestamp, OnTimerContext ctx, Collector<String> out) throws Exception {
            Long scheduled = emitTimer.value();
            if (scheduled == null || scheduled != timestamp) {
                return;
            }
            if (!Boolean.TRUE.equals(finished.value())) {
                return;
            }

            int max = maxStageCount.value() == null ? 0 : maxStageCount.value();
            out.collect("(" + ctx.getCurrentKey() + "," + max + ")");

            maxStageCount.clear();
            finished.clear();
            emitTimer.clear();
        }
    }

    private static class LocalFileSink extends RichSinkFunction<String> {

        private final String path;
        private transient BufferedWriter writer;

        private LocalFileSink(String path) {
            this.path = path;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            if (path == null) {
                throw new IllegalArgumentException("output path is null");
            }
            writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(path, false), StandardCharsets.UTF_8));
        }

        @Override
        public void invoke(String value, Context context) throws Exception {
            writer.write(value);
            writer.newLine();
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.flush();
                writer.close();
            }
        }
    }

    private interface LineParser<T> {
        T parse(String line);
    }

    private static class GzipCsvSource<T> implements SourceFunction<T> {

        private final String path;
        private final LineParser<T> parser;
        private volatile boolean running = true;

        private GzipCsvSource(String path, LineParser<T> parser) {
            this.path = path;
            this.parser = parser;
        }

        @Override
        public void run(SourceContext<T> ctx) throws Exception {
            if (path == null) {
                throw new IllegalArgumentException("Input path is null");
            }
            try (BufferedReader br = new BufferedReader(new InputStreamReader(new GZIPInputStream(new java.io.FileInputStream(path)), StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    if (line.isEmpty()) {
                        continue;
                    }
                    ctx.collect(parser.parse(line));
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }
}
